if not df_add_ptq.empty:
    _pg_check = df_add_ptq[['p', 'seed', 'phase', 'phase_step']].drop_duplicates()
    _pg_pivot = _pg_check.pivot_table(index=['p', 'seed'], columns='phase', values='phase_step', aggfunc='first')
