    fig = plt.figure(figsize=(ICLR_WIDTH, 1.80))
    gs = GridSpec(1, 3, figure=fig, left=0.08, right=0.985, top=0.70, bottom=0.26, wspace=0.30)
    ax_a, ax_b, ax_c = fig.add_subplot(gs[0]), fig.add_subplot(gs[1]), fig.add_subplot(gs[2])
    panel_bg = '#eef3f8'
