# ============================================================
# FIGURE 1 / ORIGINAL FIGURE 8
# REPRESENTATIVE GROKKING TRAJECTORY — FINAL CORRECTED VERSION
#
# Purpose:
#   Show the representative train/test trajectory and the
#   locations of the recorded post-grokking checkpoints.
#
# Figure size:
#   width  = 5.5 inches
#   height = 2.0 inches
#
# IMPORTANT:
#   - Uses the original saved training/test trajectory.
#   - Does not modify any experimental values.
#   - Phase locations are taken directly from df_ptq.
#   - All checkpoint labels are retained.
#   - Closely spaced labels use dedicated vertical annotation
#     lanes so "just grokked", "+500 steps", and "+1500 steps"
#     remain readable without covering one another.
# ============================================================

import os
import matplotlib.pyplot as plt
import matplotlib.patheffects as pe
from matplotlib.gridspec import GridSpec
from IPython.display import Image, display


# ============================================================
# SHORT PHASE LABELS
# ============================================================

def _short_phase_label(ph):
    """
    Return compact human-readable checkpoint labels.
    """

    # Explicit labels used by the final figure.
    fixed = {
        "pre_grok": "pre-grok",
        "just_grokked": "just grokked",
        "cleaned_up": "cleaned up",
    }

    if ph in fixed:
        return fixed[ph]

    # Any post_grok_N checkpoint becomes "+N steps".
    if ph.startswith("post_grok_"):
        offset = ph.replace("post_grok_", "")
        return f"+{offset} steps"

    # Use notebook mapping only for any other phase.
    if ph in PHASE_LABELS:
        return PHASE_LABELS[ph]

    return ph.replace("_", " ")


# ============================================================
# MAIN FIGURE FUNCTION
# ============================================================

def make_figure8(
    df_ptq,
    trajectory_info,
    p_primary,
    save_path
):

    # --------------------------------------------------------
    # FINAL FIGURE DIMENSIONS
    # --------------------------------------------------------

    fig = plt.figure(
        figsize=(5.5, 2.0)
    )

    gs = GridSpec(
        1,
        1,
        figure=fig,
        left=0.105,
        right=0.975,
        bottom=0.235,
        top=0.80
    )

    ax = fig.add_subplot(
        gs[0]
    )


    # --------------------------------------------------------
    # JOURNAL-STYLE AXIS
    # --------------------------------------------------------

    ax.set_facecolor("white")

    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    ax.spines["left"].set_linewidth(0.7)
    ax.spines["bottom"].set_linewidth(0.7)

    ax.grid(
        axis="both",
        color="#d9d9d9",
        linewidth=0.45,
        alpha=0.60
    )

    ax.set_axisbelow(True)


    # ========================================================
    # FIND REPRESENTATIVE TRAJECTORY
    # ========================================================

    traj = None

    for t in (trajectory_info or []):

        if (
            t["p"] == p_primary
            and t["seed"] == 0
            and t.get("train_test_history")
        ):
            traj = t["train_test_history"]
            break


    phase_list = []


    # ========================================================
    # DRAW TRAJECTORY
    # ========================================================

    if traj:

        steps = [
            s for s, tr, te in traj
        ]

        train_accs = [
            tr for s, tr, te in traj
        ]

        test_accs = [
            te for s, tr, te in traj
        ]


        # ----------------------------------------------------
        # Train trajectory
        # ----------------------------------------------------

        ax.plot(
            steps,
            train_accs,
            color=COLORS["train"],
            linewidth=1.25,
            label="Train",
            zorder=3
        )


        # ----------------------------------------------------
        # Test trajectory
        # ----------------------------------------------------

        ax.plot(
            steps,
            test_accs,
            color=COLORS["test"],
            linewidth=1.25,
            label="Test",
            zorder=3
        )


        # ====================================================
        # CHECKPOINT LOCATIONS
        # ====================================================

        phase_steps = (
            df_ptq.loc[
                (df_ptq["p"] == p_primary)
                & (df_ptq["seed"] == 0),
                [
                    "phase",
                    "phase_step"
                ]
            ]
            .drop_duplicates()
            .sort_values("phase_step")
            .reset_index(drop=True)
        )

        phase_list = list(
            phase_steps.itertuples(
                index=False
            )
        )


        # ----------------------------------------------------
        # Vertical checkpoint markers
        # ----------------------------------------------------

        for row in phase_list:

            ax.axvline(
                row.phase_step,

                color=COLORS.get(
                    row.phase,
                    "#777777"
                ),

                linewidth=0.65,
                linestyle=":",
                alpha=0.65,

                zorder=1
            )


        # ----------------------------------------------------
        # Compact legend
        # ----------------------------------------------------

        leg = ax.legend(
            loc="lower right",

            frameon=True,
            fancybox=False,

            framealpha=0.92,
            facecolor="white",
            edgecolor="0.80",

            fontsize=5.5,

            handlelength=1.5,
            handletextpad=0.4,
            labelspacing=0.25,

            borderpad=0.30,
            borderaxespad=0.25
        )


        # Additional annotation headroom
        ax.set_ylim(
            -0.04,
            1.18
        )


    else:

        no_data_placeholder(ax)
        leg = None


    # ========================================================
    # AXIS LABELS
    # ========================================================

    ax.set_xlabel(
        "Training step",
        fontsize=6.5,
        labelpad=2
    )

    ax.set_ylabel(
        "Accuracy",
        fontsize=6.5,
        labelpad=2
    )

    ax.tick_params(
        axis="both",
        labelsize=5.8,
        length=2.8,
        width=0.65
    )

    try:
        tighten_ticks(ax)
    except Exception:
        pass


    # ========================================================
    # FIGURE TITLE
    # ========================================================

    ax.set_title(
        "Representative grokking trajectory and checkpoints",
        fontsize=6.7,
        fontweight="normal",
        pad=3
    )


    # ========================================================
    # CHECKPOINT LABELS
    # ========================================================

    if phase_list:

        # x coordinate = data coordinates
        # y coordinate = axes fraction
        mixed = ax.get_xaxis_transform()

        x_min = min(steps)
        x_max = max(steps)

        total_span = max(
            x_max - x_min,
            1
        )


        # ----------------------------------------------------
        # Dedicated annotation lanes
        #
        # These are PRESENTATION positions only.
        # The actual checkpoint x positions remain unchanged.
        #
        # The important correction is that "just grokked"
        # and "+1500 steps" are deliberately placed on
        # different vertical lanes.
        # ----------------------------------------------------

        phase_y = {
            "pre_grok": 0.56,

            "just_grokked": 0.94,

            "post_grok_500": 0.61,

            "post_grok_1500": 0.79,

            "post_grok_4000": 0.69,

            "cleaned_up": 0.93,
        }


        # Small horizontal presentation shifts prevent long
        # rotated labels from visually touching each other.
        # These DO NOT change the checkpoint marker positions.
        phase_x_shift = {
            "pre_grok": 0.000,

            "just_grokked": 0.004,

            "post_grok_500": 0.006,

            "post_grok_1500": 0.012,

            "post_grok_4000": 0.006,

            "cleaned_up": -0.006,
        }


        # Generic lanes for any phase not explicitly listed
        # above (e.g. QUICK_TEST post-grok offsets).
        generic_lanes = [
            0.92,
            0.72,
            0.54,
            0.82,
        ]

        generic_index = 0


        for row in phase_list:

            ph = row.phase
            st = row.phase_step


            # ------------------------------------------------
            # Annotation y position
            # ------------------------------------------------

            if ph in phase_y:

                y_pos = phase_y[ph]

            else:

                y_pos = generic_lanes[
                    generic_index % len(generic_lanes)
                ]

                generic_index += 1


            # ------------------------------------------------
            # Annotation x position
            # ------------------------------------------------

            shift_frac = phase_x_shift.get(
                ph,
                0.005
            )

            x_text = (
                st
                + shift_frac * total_span
            )


            # ------------------------------------------------
            # Right-edge handling
            # ------------------------------------------------

            near_right_edge = (
                st >
                x_min + 0.86 * total_span
            )

            if near_right_edge:

                ha = "right"

                # Keep right-edge labels fully inside figure.
                if ph == "cleaned_up":
                    x_text = (
                        st
                        - 0.010 * total_span
                    )

            else:

                ha = "left"


            # ------------------------------------------------
            # Draw checkpoint label
            # ------------------------------------------------

            t = ax.text(
                x_text,
                y_pos,

                _short_phase_label(ph),

                fontsize=5.0,

                rotation=31,

                ha=ha,
                va="top",

                color=COLORS.get(
                    ph,
                    "#555555"
                ),

                transform=mixed,

                clip_on=False,

                zorder=5
            )


            # White outline retains readability over grid/curves.
            t.set_path_effects([
                pe.withStroke(
                    linewidth=1.6,
                    foreground="white"
                )
            ])


    # ========================================================
    # FINAL X LIMITS
    # ========================================================

    if traj:

        x_pad = (
            0.025
            * max(
                max(steps) - min(steps),
                1
            )
        )

        ax.set_xlim(
            min(steps) - x_pad,
            max(steps) + x_pad
        )


    # ========================================================
    # SAVE
    # ========================================================

    os.makedirs(
        os.path.dirname(save_path),
        exist_ok=True
    )

    png_path = (
        save_path.rsplit(
            ".pdf",
            1
        )[0]
        + ".png"
    )


    # Draw once before optional diagnostics.
    fig.canvas.draw()


    try:
        check_text_overlaps(fig)
    except Exception:
        pass


    # Vector PDF for manuscript
    fig.savefig(
        save_path,
        bbox_inches="tight",
        pad_inches=0.02
    )


    # High-resolution PNG preview
    fig.savefig(
        png_path,
        dpi=600,
        bbox_inches="tight",
        pad_inches=0.02
    )


    plt.close(fig)


    print("Saved:")
    print(save_path)
    print(png_path)


    display(
        Image(
            filename=png_path
        )
    )


# ============================================================
# GENERATE FIGURE
# ============================================================

make_figure8(
    df_add_ptq,
    addition_trajectory_info,
    P_PRIMARY,
    os.path.join(
        OUTPUT_ROOT,
        "figures",
        "fig8_grokking_trajectory_final.pdf"
    )
)

